import { Request, Response, Router } from 'express';
import { AdvanceOrderUseCase } from '../application/AdvanceOrderUseCase';
import { CancelOrderUseCase } from '../application/CancelOrderUseCase';
import { GetOrderUseCase } from '../application/GetOrderUseCase';
import { ListOrdersUseCase } from '../application/ListOrdersUseCase';
import { PlaceOrderUseCase } from '../application/PlaceOrderUseCase';
import { OrderStatus } from '../domain/OrderStatus';
import { parsePlaceOrderBody, parseStatusQuery } from './requestParsers';

export interface OrderUseCases {
  readonly placeOrder: PlaceOrderUseCase;
  readonly advanceOrder: AdvanceOrderUseCase;
  readonly cancelOrder: CancelOrderUseCase;
  readonly getOrder: GetOrderUseCase;
  readonly listOrders: ListOrdersUseCase;
}

/** URL action → target fulfilment state. */
const ACTIONS: ReadonlyArray<[string, OrderStatus]> = [
  ['pay', 'paid'],
  ['pack', 'packed'],
  ['ship', 'shipped'],
  ['deliver', 'delivered'],
];

export class OrderController {
  constructor(private readonly useCases: OrderUseCases) {}

  router(): Router {
    const router = Router();
    router.post('/', (req, res) => this.place(req, res));
    router.get('/', (req, res) => this.list(req, res));
    router.get('/:id', (req, res) => this.get(req, res));
    router.post('/:id/cancel', (req, res) => this.cancel(req, res));
    for (const [action, target] of ACTIONS) {
      router.post(`/:id/${action}`, (req, res) => this.advance(req, res, target));
    }
    return router;
  }

  private place(req: Request, res: Response): void {
    const order = this.useCases.placeOrder.execute(parsePlaceOrderBody(req.body));
    res.status(201).location(`/orders/${order.id}`).json(order);
  }

  private list(req: Request, res: Response): void {
    res.json(this.useCases.listOrders.execute(parseStatusQuery(req.query.status)));
  }

  private get(req: Request<{ id: string }>, res: Response): void {
    res.json(this.useCases.getOrder.execute(req.params.id));
  }

  private advance(req: Request<{ id: string }>, res: Response, target: OrderStatus): void {
    res.json(this.useCases.advanceOrder.execute(req.params.id, target));
  }

  private cancel(req: Request<{ id: string }>, res: Response): void {
    res.json(this.useCases.cancelOrder.execute(req.params.id));
  }
}

